#|     b0 = coeff[0][1]
#|     a1 = coeff[1][0]
#|     b1 = coeff[1][1]
#|
#|     R = parent(f)
#|     x = R.gen()
#|     num = a0*x+a1
#|     den = b0*x+b1
#|
#|     ff = f(num/den)*(den**f.degree())
#|     ffn = ff.numerator()
#|     gg = g(num/den)*(den**g.degree())
