#| /*
#|  * ECM stage 2 (standard baby-step/giant-step, x-only "product of point
#|  * differences"). Depends on mont128.cl and ecm.cl (point, mdbl, madd,
#|  * mont_*, from_mont) being prepended by the host.
#|  *
#|  * Input per work item: the stage-1 result point Q = [E]P0 in Montgomery form
#|  * (xz_in) and its curve constant b. The host chooses the giant step 2D and
#|  * passes, per prime B1<p<=B2, a pair (j,k) with p = 2D*j +/- k, 1<=k<=D.
#|  * We build baby points B[k]=[k]Q (k=1..D) and giant points G[j]=[2D*j]Q,
#|  * then accumulate prod (X(G_j)*Z(B_k) - X(B_k)*Z(G_j)); if p | ord(Q) the
#|  * corresponding factor vanishes mod the hidden prime, so gcd(prod,n) reveals
#|  * it. One gcd per work item.
#|  *
#|  * MAXD / MAXG bound the per-work-item tables (private memory).
#|  */
#| #ifndef MAXD
#| #define MAXD 64
#| #endif
#| #ifndef MAXG
#| #define MAXG 512
#| #endif
#|
#| __kernel void ecm_stage2(__global const u128* n_g,
#|                          __global const ulong* invm_g,
#|                          __global const u128* b_g,
#|                          __global const u128* xz_in,     /* Q=[E]P0, mont */
#|                          const uint D,                    /* baby 1..D */
#|                          const uint n_giant,              /* giants 1..n_giant */
#|                          __global const uint* pk_j,       /* per prime */
#|                          __global const uint* pk_k,
#|                          const uint n_primes,
#|                          __global u128* g_out) {
#|     uint i = get_global_id(0);
#|     u128 n = n_g[i]; ulong invm = invm_g[i]; u128 b = b_g[i];
#|     point Q; Q.x = xz_in[2*i]; Q.z = xz_in[2*i+1];
#|
#|     point B[MAXD + 1];
#|     B[1] = Q;
#|     if (D >= 2) B[2] = mdbl(Q, n, invm, b);
#|     for (uint k = 3; k <= D; k++)
#|         B[k] = madd(B[k-1], Q, B[k-2], n, invm);   /* [k]Q, diff [k-2]Q */
#|
#|     /* giant step is [2D]Q; G[j] = [2D*j]Q */
#|     point step = mdbl(B[D], n, invm, b);           /* [2D]Q */
#|     point G[MAXG + 1];
#|     G[1] = step;
#|     if (n_giant >= 2) G[2] = mdbl(step, n, invm, b);
#|     for (uint j = 3; j <= n_giant; j++)
#|         G[j] = madd(G[j-1], step, G[j-2], n, invm);
#|
#|     u128 acc; int have = 0;
#|     for (uint p = 0; p < n_primes; p++) {
#|         uint j = pk_j[p], k = pk_k[p];
#|         u128 t1 = mont_mul(G[j].x, B[k].z, n, invm);
#|         u128 t2 = mont_mul(B[k].x, G[j].z, n, invm);
#|         u128 diff = mont_sub(t1, t2, n);
#|         if (!have) { acc = diff; have = 1; }
#|         else acc = mont_mul(acc, diff, n, invm);
#|     }
#|     u128 a; a.x = 0; a.y = 0;
#|     if (have) a = from_mont(acc, n, invm);
#|     g_out[i] = gcd128(a, n);
#| }

#@ FILE code/gpu/las_profiling.md 644 2449 82234399a3b766d62657ac3f166da9264aae25943489c7df1f6933df646f165b text
#| # Measuring the sieving vs cofactorization split in `las`
#|
#| The GPU ECM kernels here accelerate **cofactorization** only. How much that
#| helps end to end is capped by cofactorization's share of `las` time (Amdahl).
#| That share is **not fixed** — it grows sharply with `mfb` (the large-prime
#| cofactor bound), and the real configs use large `mfb`. Measure it on your own
#| config rather than assuming; `las_split.py` does the arithmetic.
#|
#| ## Build `las`
#|
#| On top of the `testbench` recipe in `../../docs/las_gpu_notes.md`, `las` also
#| needs hwloc:
#|
#| ```bash
#| apt-get install -y libgmp-dev libhwloc-dev python3-flask python3-requests
#| cd code/cado
#| make las makefb          # -> build/<host>/sieve/{las,makefb}
#| ```
#|
#| `las` prints the split only when built **without** `-production` (the default
#| `make` build is fine) and run at **verbose level 2** (`-v -v`).
#|
#| ## Run and parse
#|
#| Quickest self-contained check, using a bundled test polynomial:
#|
#| ```bash
#| B=code/cado/build/vm/sieve
#| P=code/cado/tests/misc/c60.poly
#| $B/makefb -poly $P -lim 111342 -maxbits 10 -out /tmp/c60.fb1
#| $B/las -poly $P -fb1 /tmp/c60.fb1 -lim0 78682 -lim1 111342 \
#|        -lpb0 18 -lpb1 19 -mfb0 17 -mfb1 80 -I 10 \
#|        -q0 200000 -q1 202000 -v -v -t 1 \
#|   | python3 code/gpu/las_split.py
#| ```
#|
#| `las_split.py` reads the `# Total cpu time … sieving S … factor F …` line and
#| prints the cofactorization fraction plus the Amdahl ceiling for a
#| cofactorization-only GPU speedup.
#|
#| To profile a **real** config from this repo, run `las` with that config's
#| `lpb`/`mfb`/`A`/`lim` (see `code/config/nNNN.config` and the `las` calls in
#| `code/helpers.py` `do_algebraic_query_sieving` / `do_fb_extension_sieving`) on
#| its generated poly + factor base, adding `-v -v`, and pipe to `las_split.py`.
#|
#| ## Measured on this box (c60 poly, one q-block) — the split is mfb-driven
#|
#| | `mfb1` | sieving | cofactor | cofactor share |
#| |------:|--------:|---------:|---------------:|
#| | 38 | 1.1 s | 0.1 s | **8%** |
#| | 60 | 1.2 s | 1.0 s | 45% |
#| | 80 | 1.2 s | 4.6 s | **79%** |
#|
#| At `mfb1=80` cofactorization is ~79% of sieve+cofactor, so moving only
#| cofactorization to the GPU has an Amdahl ceiling of `1/(1-0.79) ≈ 4.8×`
#| end to end. The production configs use larger `mfb` still (e.g. n1024:
#| `sieve.mfb1=120`, `desc.mfb1=150`), so cofactorization is expected to be the
#| **dominant** `las` cost there — which is exactly where a fast GPU cofactorizer
#| pays off. Measure your real config to get the exact ceiling.

#@ FILE code/gpu/las_split.py 644 2680 2e4bedf481c3b7a43bf58095976b475e40ffecd3f83c6e8ed6202f89881bb082 text
#| #!/usr/bin/env python3
#| """
#| Parse a CADO `las` verbose run and report the sieving-vs-cofactorization
#| split -- the Amdahl fraction that caps how much GPU cofactorization can help
#| end to end.
#|
#| `las` (built WITHOUT -production, run at verbose level 2, e.g. `-v -v`) prints:
#|
#|   # Total cpu time T s, useful U s [norm a+b, sieving S (...), factor F (...),
#|     rest R], wasted+waited W s, rest ...
#|
#| where `sieving S` is total sieve time and `factor F` is cofactorization time.
#| The cofactorization fraction of the *useful* CPU time is F / (norm + S + F + R);
#| the fraction of sieve+cofac is F / (S + F).
#|
#| Usage:
#|   <las> -v -v <las-args...>  2>&1 | python3 las_split.py
#|   python3 las_split.py las_output.log
#|
#| See las_profiling.md for how to produce the input on a real config.
#| """
#| import re
#| import sys
#|
#| LINE = re.compile(
#|     r"# Total cpu time ([\d.]+)s, useful ([\d.]+)s \[norm ([\d.]+)\+([\d.]+), "
#|     r"sieving ([\d.]+).*?factor ([\d.]+)")
#|
#|
#| def parse(text):
#|     rows = []
#|     for m in LINE.finditer(text):
#|         total, useful, n0, n1, sieving, factor = map(float, m.groups())
#|         rows.append(dict(total=total, useful=useful, norm=n0 + n1,
#|                          sieving=sieving, factor=factor))
#|     return rows
#|
#|
#| def main():
#|     text = open(sys.argv[1]).read() if len(sys.argv) > 1 else sys.stdin.read()
#|     rows = parse(text)
#|     if not rows:
#|         sys.stderr.write(
#|             "no '# Total cpu time ... sieving ... factor ...' line found.\n"
#|             "Build las WITHOUT -production and run it at verbose level 2 "
#|             "(-v -v); see las_profiling.md.\n")
#|         return 2
#|     # aggregate (a run may print several special-q blocks)
#|     norm = sum(r["norm"] for r in rows)
#|     siev = sum(r["sieving"] for r in rows)
#|     fact = sum(r["factor"] for r in rows)
#|     useful = sum(r["useful"] for r in rows)
#|     sf = siev + fact
#|     print("las timing over %d block(s):" % len(rows))
#|     print("  norm       : %10.2f s" % norm)
#|     print("  sieving    : %10.2f s" % siev)
#|     print("  cofactor   : %10.2f s" % fact)
#|     print("  useful cpu : %10.2f s" % useful)
#|     print()
#|     if sf > 0:
#|         print("  cofactorization / (sieving+cofactor) = %.1f%%" % (100 * fact / sf))
#|     if useful > 0:
#|         f = fact / useful
#|         print("  cofactorization / useful cpu         = %.1f%%" % (100 * f))
#|         print()
#|         print("  Amdahl ceiling if ONLY cofactorization is moved to the GPU:")
#|         for sp in (5, 10, 50, 1e9):
#|             cap = 1.0 / ((1 - f) + f / sp)
#|             tag = "inf" if sp > 1e8 else "%gx" % sp
#|             print("    kernel %-4s faster -> %.2fx end-to-end" % (tag, cap))
#|     return 0
#|
#|
#| if __name__ == "__main__":
#|     raise SystemExit(main())

#@ FILE code/gpu/mont128.cl 644 4154 8127ca85ab4b507b6bb446d21d1e136004d7776bb42d63c66778639813684937 text
#| /*
#|  * 128-bit fixed-width Montgomery arithmetic for OpenCL, matching CADO's
#|  * utils/arith/modredc_2ul2 representation: modulus n < 2^127 (odd), two
#|  * 64-bit limbs little-endian (lo, hi), R = 2^128, invm = -n^{-1} mod 2^64.
#|  * Residues are kept in Montgomery form a*R mod n.
#|  *
#|  * This header is shared by the ECM kernels and by the arithmetic unit test.
#|  * mul_hi(ulong,ulong) supplies the high 64 bits of a 64x64 product.
#|  */
#|
#| typedef ulong2 u128;   /* .x = low limb, .y = high limb */
#|
#| inline uint addc64(ulong a, ulong b, uint cin, ulong *out) {
#|     ulong s = a + cin;
#|     uint c1 = (s < a);
#|     s += b;
#|     *out = s;
#|     return c1 + (s < b);
#| }
#|
#| inline int geq128(u128 a, u128 b) {
#|     return (a.y > b.y) || (a.y == b.y && a.x >= b.x);
#| }
#|
#| inline u128 sub128(u128 a, u128 b) {   /* assumes a >= b */
#|     u128 r;
#|     r.x = a.x - b.x;
#|     r.y = a.y - b.y - (a.x < b.x);
#|     return r;
#| }
#|
#| inline u128 add128(u128 a, u128 b) {   /* mod 2^128 */
#|     u128 r;
#|     r.x = a.x + b.x;
#|     r.y = a.y + b.y + (r.x < a.x);
#|     return r;
#| }
#|
#| /* Montgomery add: (a+b) mod n */
#| inline u128 mont_add(u128 a, u128 b, u128 n) {
#|     u128 r = add128(a, b);
#|     /* a,b < n < 2^127 so a+b < 2^128: a carry out or r>=n both mean subtract */
#|     int carry = (r.y < a.y) || (r.x < a.x && r.y == a.y);
#|     if (carry || geq128(r, n))
#|         r = sub128(r, n);
#|     return r;
#| }
#|
#| inline u128 mont_sub(u128 a, u128 b, u128 n) {
#|     if (geq128(a, b))
#|         return sub128(a, b);
#|     return sub128(add128(a, n), b);   /* a + n - b, a<b<n so a+n < 2^128 */
#| }
#|
#| /*
#|  * CIOS Montgomery multiplication for L=2 limbs.
#|  * Returns a*b*R^{-1} mod n, with 0 <= result < n.
#|  */
#| inline u128 mont_mul(u128 a, u128 b, u128 n, ulong invm) {
#|     ulong an[2] = {a.x, a.y};
#|     ulong bn[2] = {b.x, b.y};
#|     ulong nn[2] = {n.x, n.y};
#|     ulong t0 = 0, t1 = 0, t2 = 0;
#|
#|     for (int i = 0; i < 2; i++) {
#|         ulong bi = bn[i];
#|         /* t += a * bi */
#|         ulong lo0 = an[0] * bi, hi0 = mul_hi(an[0], bi);
#|         ulong lo1 = an[1] * bi, hi1 = mul_hi(an[1], bi);
#|         uint c;
#|         c = addc64(t0, lo0, 0, &t0);          /* t0 += lo0 */
#|         ulong carry_hi0 = hi0 + c;             /* hi0 < 2^64-1 so no overflow */
#|         c = addc64(t1, lo1, 0, &t1);          /* t1 += lo1 */
#|         ulong carry = hi1 + c;
#|         c = addc64(t1, carry_hi0, 0, &t1);    /* t1 += hi0 + c0 */
#|         carry += c;
#|         t2 += carry;                           /* t2 += hi1 + carries */
#|
#|         /* m = t0 * invm mod 2^64; t += m * n; then shift right one limb */
#|         ulong m = t0 * invm;
#|         ulong ml0 = m * nn[0], mh0 = mul_hi(m, nn[0]);
#|         ulong ml1 = m * nn[1], mh1 = mul_hi(m, nn[1]);
#|         ulong tmp;
#|         c = addc64(t0, ml0, 0, &tmp);          /* t0 + ml0, low limb -> 0, keep carry */
#|         ulong carry_mh0 = mh0 + c;
#|         c = addc64(t1, ml1, 0, &t1);
#|         ulong carry2 = mh1 + c;
#|         c = addc64(t1, carry_mh0, 0, &t1);
#|         carry2 += c;
#|         /* shift: new t0=t1, t1=t2+carry2, t2=carry out */
#|         ulong newt1;
#|         c = addc64(t2, carry2, 0, &newt1);
#|         t0 = t1;
#|         t1 = newt1;
#|         t2 = c;
#|     }
#|
#|     u128 r; r.x = t0; r.y = t1;
#|     /* t2 holds a possible carry limb; reduce so that 0 <= r < n */
#|     if (t2 || geq128(r, n))
#|         r = sub128(r, n);
#|     return r;
#| }
#|
#| inline u128 mont_sqr(u128 a, u128 n, ulong invm) { return mont_mul(a, a, n, invm); }
#|
#| /* binary GCD of two 128-bit integers (not in Montgomery form) */
#| inline u128 gcd128(u128 a, u128 b) {
#|     if (a.x == 0 && a.y == 0) return b;
#|     if (b.x == 0 && b.y == 0) return a;
#|     int shift = 0;
#|     while (((a.x | b.x) & 1) == 0) {
#|         a.x = (a.x >> 1) | (a.y << 63); a.y >>= 1;
#|         b.x = (b.x >> 1) | (b.y << 63); b.y >>= 1;
#|         shift++;
#|     }
#|     while ((a.x & 1) == 0) { a.x = (a.x >> 1) | (a.y << 63); a.y >>= 1; }
#|     do {
#|         while ((b.x & 1) == 0) { b.x = (b.x >> 1) | (b.y << 63); b.y >>= 1; }
#|         if (geq128(a, b)) { u128 t = a; a = b; b = t; }   /* a = min, b = max */
#|         b = sub128(b, a);
#|     } while (!(b.x == 0 && b.y == 0));
#|     /* a <<= shift */
#|     for (int i = 0; i < shift; i++) { a.y = (a.y << 1) | (a.x >> 63); a.x <<= 1; }
#|     return a;
#| }

#@ FILE code/gpu/mont32.cl 644 4205 0c9f3f7d5e8455141c34bdce7926dc5571c0667e0abc6a8b86ccaf93d79f1e58 text
#| /*
#|  * 128-bit Montgomery arithmetic with 32-bit limbs, for GPUs whose 64-bit
#|  * integer multiply is synthesized (AMD GCN / Vega, most consumer/pro cards).
#|  * Every partial product here is a 32x32 -> 64 multiply (native `uint*uint`
#|  * widened to `ulong`), so it needs no `mul_hi(ulong,...)`. Same math as
#|  * mont128.cl (CADO modredc_2ul2), different limb width.
#|  *
#|  * A 128-bit value is uint4 = (limb0..limb3), little-endian. Modulus n < 2^127
#|  * odd; R = 2^128; ninv = -n^{-1} mod 2^32. Residues are in Montgomery form.
#|  *
#|  * NLIMBS is fixed at 4 (128-bit). The CIOS loops are written generically over
#|  * NLIMBS so the same code can be widened later.
#|  */
#| #define NLIMBS 4
#|
#| typedef uint4 u128_32;
#|
#| inline void ld(uint *l, u128_32 a) { l[0]=a.x; l[1]=a.y; l[2]=a.z; l[3]=a.w; }
#| inline u128_32 st(const uint *l) { return (u128_32)(l[0], l[1], l[2], l[3]); }
#|
#| inline int geq(const uint *a, const uint *b) {
#|     for (int i = NLIMBS - 1; i >= 0; i--) {
#|         if (a[i] != b[i]) return a[i] > b[i];
#|     }
#|     return 1;
#| }
#|
#| inline void sub_in(uint *a, const uint *b) {   /* a -= b (assumes a>=b) */
#|     ulong borrow = 0;
#|     for (int i = 0; i < NLIMBS; i++) {
#|         ulong d = (ulong)a[i] - b[i] - borrow;
#|         a[i] = (uint)d;
#|         borrow = (d >> 63) & 1;   /* set if underflow */
#|     }
#| }
#|
#| inline u128_32 m32_add(u128_32 A, u128_32 B, u128_32 N) {
#|     uint a[NLIMBS], b[NLIMBS], n[NLIMBS];
#|     ld(a, A); ld(b, B); ld(n, N);
#|     ulong c = 0;
#|     for (int i = 0; i < NLIMBS; i++) { ulong s = (ulong)a[i] + b[i] + c; a[i] = (uint)s; c = s >> 32; }
#|     if (c || geq(a, n)) sub_in(a, n);
#|     return st(a);
#| }
#|
#| inline u128_32 m32_sub(u128_32 A, u128_32 B, u128_32 N) {
#|     uint a[NLIMBS], b[NLIMBS], n[NLIMBS];
#|     ld(a, A); ld(b, B); ld(n, N);
#|     if (geq(a, b)) { sub_in(a, b); return st(a); }
#|     /* a + n - b */
#|     ulong c = 0;
#|     for (int i = 0; i < NLIMBS; i++) { ulong s = (ulong)a[i] + n[i] + c; a[i] = (uint)s; c = s >> 32; }
#|     sub_in(a, b);
#|     return st(a);
#| }
#|
#| /* CIOS Montgomery multiply, 32-bit limbs, 64-bit accumulator. */
#| inline u128_32 m32_mul(u128_32 A, u128_32 B, u128_32 N, uint ninv) {
#|     uint a[NLIMBS], b[NLIMBS], n[NLIMBS];
#|     ld(a, A); ld(b, B); ld(n, N);
#|     uint t[NLIMBS + 2];
#|     for (int i = 0; i < NLIMBS + 2; i++) t[i] = 0;
#|
#|     for (int i = 0; i < NLIMBS; i++) {
#|         ulong C = 0;
#|         uint bi = b[i];
#|         for (int j = 0; j < NLIMBS; j++) {
#|             ulong p = (ulong)a[j] * bi + t[j] + C;
#|             t[j] = (uint)p;
#|             C = p >> 32;
#|         }
#|         ulong s = (ulong)t[NLIMBS] + C;
#|         t[NLIMBS] = (uint)s;
#|         t[NLIMBS + 1] = (uint)(s >> 32);
#|
#|         uint m = t[0] * ninv;
#|         C = ((ulong)m * n[0] + t[0]) >> 32;   /* low limb becomes 0 */
#|         for (int j = 1; j < NLIMBS; j++) {
#|             ulong p = (ulong)m * n[j] + t[j] + C;
#|             t[j - 1] = (uint)p;
#|             C = p >> 32;
#|         }
#|         s = (ulong)t[NLIMBS] + C;
#|         t[NLIMBS - 1] = (uint)s;
#|         t[NLIMBS] = t[NLIMBS + 1] + (uint)(s >> 32);
#|     }
#|
#|     uint r[NLIMBS];
#|     for (int i = 0; i < NLIMBS; i++) r[i] = t[i];
#|     if (t[NLIMBS] || geq(r, n)) sub_in(r, n);
#|     return st(r);
#| }
#|
#| inline u128_32 m32_sqr(u128_32 a, u128_32 n, uint ninv) { return m32_mul(a, a, n, ninv); }
#|
#| /* binary gcd of two 128-bit integers (not in Montgomery form) */
#| inline int is_zero(const uint *a) { return (a[0]|a[1]|a[2]|a[3]) == 0; }
#| inline void shr1(uint *a) {
#|     for (int i = 0; i < NLIMBS - 1; i++) a[i] = (a[i] >> 1) | (a[i+1] << 31);
#|     a[NLIMBS-1] >>= 1;
#| }
#| inline void shl1(uint *a) {
#|     for (int i = NLIMBS - 1; i > 0; i--) a[i] = (a[i] << 1) | (a[i-1] >> 31);
#|     a[0] <<= 1;
#| }
#| inline u128_32 m32_gcd(u128_32 A, u128_32 B) {
#|     uint a[NLIMBS], b[NLIMBS];
#|     ld(a, A); ld(b, B);
#|     if (is_zero(a)) return B;
#|     if (is_zero(b)) return A;
#|     int shift = 0;
#|     while (((a[0] | b[0]) & 1) == 0) { shr1(a); shr1(b); shift++; }
#|     while ((a[0] & 1) == 0) shr1(a);
#|     do {
#|         while ((b[0] & 1) == 0) shr1(b);
#|         if (geq(a, b)) { uint tmp[NLIMBS]; for(int i=0;i<NLIMBS;i++){tmp[i]=a[i];a[i]=b[i];b[i]=tmp[i];} }
#|         sub_in(b, a);   /* b = b - a, b was >= a */
#|     } while (!is_zero(b));
#|     for (int i = 0; i < shift; i++) shl1(a);
#|     return st(a);
#| }

#@ FILE code/gpu/test_mont128.py 644 4103 6e9efb2f26b5fe9d6b4b23a4909df3d5fc3b8bf20107d21ea9a908870dd3cb07 text
#| #!/usr/bin/env python3
#| """Unit-test the 128-bit Montgomery ops in mont128.cl against Python."""
#| import os
#| import random
#| import numpy as np
#| import pyopencl as cl
