#|             poly_m = nf_elt.polynomial().change_ring(ZN)(m)
#|             #poly_m_inv = inverse_mod(poly_m, N)
#|             SU_m *= ZN(poly_m)**(-e*exp)
#|
#|         assert r(ZN(m))**e == SU_m
#|         return r
#|
#|     # usual case
#|     r = padic_root_of_algebraic_product(TTplus, TTminus,
#|                                         f, p, e,
#|                                         pre_multiply_root=pre_multiply_root)
#|
